// Mock content images from Unsplash, with credits. URLs and photo pages are kept as found. The images the
// app draws are bundled (assets/images/content/<key>.jpg, downloaded at 800 px for shops, 400 px for products and
// 640 px for the shops added later)
// so they load inside the docs site, whose host blocks external images; `imageSource` returns them. The 12 mock shops
// are listed in docs/deliver/prototype.md (Mocked content); credits stay in this file and are not shown in the UI.
// Unsplash licence: free to use, including copying and bundling; credit the photographer and Unsplash where the image appears.

import { Platform } from 'react-native';

import { bundledImages } from './images.generated';

export type ImageSubject = 'shop' | 'product' | 'category';
export type ImageKind = 'shopfront' | 'interior' | 'product' | 'category';
export type ImageRatio = '4:3' | '3:2' | '1:1';

export type ContentImage = {
  key: string;
  subject: ImageSubject;
  /** The shop, product or category the image stands for in the mock content. */
  for: string;
  kind: ImageKind;
  /** The Unsplash photo page. */
  page: string;
  /** The image URL, without size parameters. */
  image: string;
  photographer: string;
  /** The photographer's Unsplash profile. */
  profile: string;
  ratioHint: ImageRatio;
  /** Checked against the live Unsplash page when the manifest was made. */
  verified: boolean;
};

